#!/usr/bin/env python3# -*- coding: utf-8 -*-"""download_market_input.pyExternal market data layer for the Trade Reconciliation System.Purpose:- Read internal trade input CSV- Extract unique symbols and required trade dates- Fetch historical daily market prices from Alpha Vantage- Save normalized market data to output/market_prices.csvNotes:- Uses Alpha Vantage TIME_SERIES_DAILY endpoint- Free tier is rate-limited, so fetch once per unique symbol- Uses CSV response format for simpler parsing"""from __future__ import annotationsimport argparseimport sysimport timefrom dataclasses import dataclassfrom io import StringIOfrom pathlib import Pathfrom typing import Iterableimport pandas as pdimport requests# -----------------------------# Configuration# -----------------------------DEFAULT_API_KEY = "2B1V00IN53XV5Z0A"BASE_URL = "https://www.alphavantage.co/query"REQUIRED_INPUT_COLUMNS = {    "trade_id",    "symbol",    "trade_date",    "side",    "quantity",    "trade_price",}@dataclassclass DownloadConfig:    api_key: str    input_file: Path    output_file: Path    request_sleep_seconds: float = 15.0    timeout_seconds: int = 30    use_compact_output: bool = True# -----------------------------# Logging helpers# -----------------------------def log_info(message: str) -> None:    print(f"[INFO] {message}")def log_warn(message: str) -> None:    print(f"[WARN] {message}")def log_error(message: str) -> None:    print(f"[ERROR] {message}")# -----------------------------# Input handling# -----------------------------def load_and_validate_input(input_file: Path) -> pd.DataFrame:    """    Load the internal trades CSV and validate required columns.    """    if not input_file.exists():        raise FileNotFoundError(f"Input file not found: {input_file}")    df = pd.read_csv(input_file)    missing = REQUIRED_INPUT_COLUMNS - set(df.columns)    if missing:        raise ValueError(            f"Missing required columns in input file: {sorted(missing)}"        )    df = df.copy()    df["symbol"] = df["symbol"].astype(str).str.upper().str.strip()    df["trade_date"] = pd.to_datetime(df["trade_date"], errors="coerce")    bad_dates = df["trade_date"].isna().sum()    if bad_dates:        log_warn(f"{bad_dates} rows have invalid trade_date and will be ignored.")    df = df.dropna(subset=["trade_date"])    df = df[df["symbol"] != ""]    return dfdef get_unique_symbols(df: pd.DataFrame) -> list[str]:    """    Return sorted unique symbols from the trades dataframe.    """    return sorted(df["symbol"].dropna().unique().tolist())def get_required_trade_dates(df: pd.DataFrame) -> set[pd.Timestamp]:    """    Return the set of trade dates present in the internal file.    """    return set(pd.to_datetime(df["trade_date"]).dt.normalize())# -----------------------------# Alpha Vantage client# -----------------------------class AlphaVantageClient:    """    Small Alpha Vantage client for TIME_SERIES_DAILY CSV downloads.    """    def __init__(self, api_key: str, timeout_seconds: int = 30) -> None:        self.api_key = api_key        self.timeout_seconds = timeout_seconds        self.session = requests.Session()    def fetch_daily_prices(self, symbol: str, use_compact_output: bool = True) -> pd.DataFrame:        """        Fetch daily historical prices for a symbol from Alpha Vantage.        Returns a dataframe with:        - timestamp        - open        - high        - low        - close        - volume        - symbol        """        params = {            "function": "TIME_SERIES_DAILY",            "symbol": symbol,            "apikey": self.api_key,            "datatype": "csv",            "outputsize": "compact" if use_compact_output else "full",        }        response = self.session.get(            BASE_URL,            params=params,            timeout=self.timeout_seconds,        )        response.raise_for_status()        raw_text = response.text.strip()        # Alpha Vantage sometimes returns JSON-shaped error payloads even if CSV is requested.        if raw_text.startswith("{"):            raise ValueError(                f"Alpha Vantage returned JSON/error payload for {symbol}: "                f"{raw_text[:250]}"            )        df = pd.read_csv(StringIO(raw_text))        expected_columns = {"timestamp", "open", "high", "low", "close", "volume"}        missing = expected_columns - set(df.columns)        if missing:            raise ValueError(                f"Unexpected response for {symbol}. Missing columns: {sorted(missing)}. "                f"Returned columns: {list(df.columns)}"            )        df["timestamp"] = pd.to_datetime(df["timestamp"], errors="coerce").dt.normalize()        df["symbol"] = symbol        numeric_cols = ["open", "high", "low", "close", "volume"]        for col in numeric_cols:            df[col] = pd.to_numeric(df[col], errors="coerce")        df = df.dropna(subset=["timestamp", "close"])        return df# -----------------------------# Market data transformation# -----------------------------def filter_to_required_dates(    market_df: pd.DataFrame,    required_dates: set[pd.Timestamp],) -> pd.DataFrame:    """    Keep only rows whose timestamp matches a trade date in the internal input.    """    if not required_dates:        return market_df.iloc[0:0].copy()    return market_df[market_df["timestamp"].isin(required_dates)].copy()def build_market_price_dataset(    trades_df: pd.DataFrame,    client: AlphaVantageClient,    config: DownloadConfig,) -> pd.DataFrame:    """    Download daily prices once per unique symbol and filter to required trade dates.    """    symbols = get_unique_symbols(trades_df)    required_dates = get_required_trade_dates(trades_df)    if not symbols:        raise ValueError("No valid symbols found in input file.")    log_info(f"Unique symbols to fetch: {len(symbols)}")    log_info(f"Unique trade dates needed: {len(required_dates)}")    all_frames: list[pd.DataFrame] = []    failures: list[dict[str, str]] = []    for idx, symbol in enumerate(symbols, start=1):        log_info(f"Fetching {symbol} ({idx}/{len(symbols)})")        try:            raw_market_df = client.fetch_daily_prices(                symbol=symbol,                use_compact_output=config.use_compact_output,            )            filtered_market_df = filter_to_required_dates(raw_market_df, required_dates)            if filtered_market_df.empty:                log_warn(f"No market rows found for required dates for symbol {symbol}.")            else:                all_frames.append(filtered_market_df)        except Exception as exc:            log_warn(f"Failed to fetch market data for {symbol}: {exc}")            failures.append({                "symbol": symbol,                "error_message": str(exc),            })        # Respect free-tier usage by pausing between requests.        # You can reduce this if you move to premium.        if idx < len(symbols):            time.sleep(config.request_sleep_seconds)    if all_frames:        market_prices_df = pd.concat(all_frames, ignore_index=True)    else:        market_prices_df = pd.DataFrame(            columns=["timestamp", "open", "high", "low", "close", "volume", "symbol"]        )    # Add a companion failure frame for auditability.    failures_df = pd.DataFrame(failures)    if not failures_df.empty:        failure_file = config.output_file.parent / "market_data_failures.csv"        failures_df.to_csv(failure_file, index=False)        log_info(f"Saved failure report to: {failure_file}")    # Normalize schema for downstream reconciliation.    market_prices_df = market_prices_df.rename(        columns={            "timestamp": "date",            "close": "market_close_price",        }    )    ordered_cols = [        "symbol",        "date",        "open",        "high",        "low",        "market_close_price",        "volume",    ]    market_prices_df = market_prices_df[ordered_cols].sort_values(        by=["symbol", "date"]    ).reset_index(drop=True)    return market_prices_df# -----------------------------# Output handling# -----------------------------def save_market_prices(df: pd.DataFrame, output_file: Path) -> None:    output_file.parent.mkdir(parents=True, exist_ok=True)    df.to_csv(output_file, index=False)    log_info(f"Saved market prices to: {output_file}")    log_info(f"Rows written: {len(df)}")# -----------------------------# CLI# -----------------------------def parse_args(argv: Iterable[str]) -> argparse.Namespace:    parser = argparse.ArgumentParser(        description="Download external market prices from Alpha Vantage."    )    parser.add_argument(        "--input-file",        required=True,        help="Path to internal trades CSV file.",    )    parser.add_argument(        "--output-file",        default="output/market_prices.csv",        help="Path to save the normalized market prices CSV.",    )    parser.add_argument(        "--api-key",        default=DEFAULT_API_KEY,        help="Alpha Vantage API key.",    )    parser.add_argument(        "--sleep-seconds",        type=float,        default=15.0,        help="Seconds to pause between API calls.",    )    parser.add_argument(        "--timeout-seconds",        type=int,        default=30,        help="HTTP timeout in seconds.",    )    parser.add_argument(        "--full-output",        action="store_true",        help="Use outputsize=full. Premium-only on Alpha Vantage.",    )    return parser.parse_args(list(argv))def main(argv: Iterable[str]) -> int:    args = parse_args(argv)    config = DownloadConfig(        api_key=args.api_key,        input_file=Path(args.input_file),        output_file=Path(args.output_file),        request_sleep_seconds=args.sleep_seconds,        timeout_seconds=args.timeout_seconds,        use_compact_output=not args.full_output,    )    try:        log_info("Loading internal trades input")        trades_df = load_and_validate_input(config.input_file)        log_info("Initializing Alpha Vantage client")        client = AlphaVantageClient(            api_key=config.api_key,            timeout_seconds=config.timeout_seconds,        )        log_info("Building market price dataset")        market_prices_df = build_market_price_dataset(            trades_df=trades_df,            client=client,            config=config,        )        save_market_prices(market_prices_df, config.output_file)        if market_prices_df.empty:            log_warn("No market prices were downloaded for the requested trade dates.")        else:            log_info("External market data layer completed successfully.")        return 0    except Exception as exc:        log_error(str(exc))        return 1if __name__ == "__main__":    raise SystemExit(main(sys.argv[1:]))